INSERT INTO public."TblP127Post"("PostID","Slug","Category","Status","JourneyID","RecordDate","CheckedAt","SortOrder","Revision","CreatedAt","UpdatedAt") VALUES('12700000-0000-4000-8000-000000000101','why-this-journey','about','published',NULL,NULL,NULL,101,1,'2026-09-21T00:00:00Z','2026-09-21T00:00:00Z') ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127PostTranslation"("PostID","Language","Title","Summary","IsPublished","Blocks") VALUES('12700000-0000-4000-8000-000000000101','zh','為什麼走這一趟','帶著自己的信念，走近他人的善意。',true,'[{"type": "paragraph", "text": "我在慈濟工作，看見許多人把關懷化為日常的行動，也因此想走出去，看看自己熟悉的圈子之外，還有哪些溫暖的力量。"}, {"type": "paragraph", "text": "回望戰後不到百年的台灣，慈濟、佛光、中台、法鼓等佛教團體逐漸成長，各自發展出回應社會需要的方式。每當想到這座島上，有這麼多人長年投入照顧、教育與助人的工作，我便心懷感謝，也想更靠近一些，理解這些力量如何形成，又如何延續。"}, {"type": "paragraph", "text": "我並非佛教徒。我相信物質世界的規律，相信科學能帶領我們理解宇宙。但這份信念，並不妨礙我敬重有信仰的人。我未必接受相同的解釋，卻能感受他們伸手助人的真誠。"}, {"type": "paragraph", "text": "於是，我想每年留幾天，以四座名山為停留的地方，繞台灣走一回。向主人致意，安靜看看；若事先聯繫到合適的機會，也幫忙掃地、整理環境，或做一點農務。在四山之間，搭車、走路、住上一晚，認識沿途的人與生活。"}, {"type": "paragraph", "text": "我嚮往西班牙的朝聖之路，也嚮往日本的四國遍路。這份嚮往讓我回頭看見，台灣也有值得用一段旅程來認識的故事。"}, {"type": "paragraph", "text": "四座名山，是我開始理解這些故事的入口。希望有一天，來自不同地方、懷抱不同信念的人，也願意循著這條路，看看台灣如何在人與人之間，實踐關懷。"}, {"type": "quote", "text": "這條路，先從我的一次出發開始。"}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127PostTranslation"("PostID","Language","Title","Summary","IsPublished","Blocks") VALUES('12700000-0000-4000-8000-000000000101','en','Why make this journey?','Bring your own beliefs. Meet the kindness of others.',true,'[{"type": "paragraph", "text": "I work at Tzu Chi, where I see care expressed through everyday actions. This has made me want to step beyond my familiar surroundings and discover other sources of warmth in society."}, {"type": "paragraph", "text": "In the decades since the war, Buddhist communities including Tzu Chi, Fo Guang Shan, Chung Tai and Dharma Drum Mountain have grown in Taiwan, each developing its own ways to respond to social needs. I feel grateful for the people who devote themselves to care, education and helping others. I want to understand how that commitment begins and how it endures."}, {"type": "paragraph", "text": "I am not a Buddhist. I believe in the laws of the physical world and in science as a way to understand the universe. That conviction does not keep me from respecting people of faith. We may explain the world differently, yet I can appreciate the sincerity of their care for others."}, {"type": "paragraph", "text": "I hope to set aside a few days each year to travel around Taiwan, stopping at these four places. I will greet my hosts and take time to observe. If a suitable opportunity can be arranged in advance, I would also like to help with simple tasks. Between the four stops, there will be buses, trains, walks and overnight stays: opportunities to encounter everyday life."}, {"type": "paragraph", "text": "I have long been drawn to the Camino in Spain and the Shikoku pilgrimage in Japan. That longing has helped me notice the stories here in Taiwan that are worth discovering through a journey."}, {"type": "paragraph", "text": "These four places are my starting points. I hope that people from different places and with different beliefs will one day follow this route and see how care takes shape between people in Taiwan."}, {"type": "quote", "text": "This route begins with one departure: my own."}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127Post"("PostID","Slug","Category","Status","JourneyID","RecordDate","CheckedAt","SortOrder","Revision","CreatedAt","UpdatedAt") VALUES('12700000-0000-4000-8000-000000000102','how-to-use','about','published',NULL,NULL,NULL,102,1,'2026-09-21T00:00:00Z','2026-09-21T00:00:00Z') ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127PostTranslation"("PostID","Language","Title","Summary","IsPublished","Blocks") VALUES('12700000-0000-4000-8000-000000000102','zh','這條路，怎麼走？','一次走完，或分次到訪。把時間留給途中。',true,'[{"type": "paragraph", "text": "四個停留點提供方向，旅程的節奏則由你決定。可以一次走完，也可以分次到訪；可以順時針，也可以逆時針。"}, {"type": "paragraph", "text": "出發前，閱讀四山介紹與路線指南，確認參訪規定及當日交通。途中依自己的信念表達敬意，尊重現場作息與拍攝規定。"}, {"type": "paragraph", "text": "本網站是個人的文化旅行與寫作計畫，並非四個團體共同主辦的官方路線。四山之間的連線表示旅行順序，不代表連續步道。"}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127PostTranslation"("PostID","Language","Title","Summary","IsPublished","Blocks") VALUES('12700000-0000-4000-8000-000000000102','en','A route of your own','Travel in one journey or return in stages.',true,'[{"type": "paragraph", "text": "The four stops give the journey a shape; you choose its pace. Complete the circuit in one trip or visit in stages, in either direction."}, {"type": "paragraph", "text": "Read the guides before leaving and confirm current visiting arrangements and transport. Express respect in a way consistent with your beliefs, and follow local routines and photography rules."}, {"type": "paragraph", "text": "This is a personal cultural travel and writing project, not an official route jointly operated by the four communities. Connections between the stops show a possible sequence, not a continuous walking trail."}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127Post"("PostID","Slug","Category","Status","JourneyID","RecordDate","CheckedAt","SortOrder","Revision","CreatedAt","UpdatedAt") VALUES('12700000-0000-4000-8000-000000000110','dharma-drum','mountains','published',NULL,NULL,NULL,110,1,'2026-09-21T00:00:00Z','2026-09-21T00:00:00Z') ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127PostTranslation"("PostID","Language","Title","Summary","IsPublished","Blocks") VALUES('12700000-0000-4000-8000-000000000110','zh','法鼓山','四山之一・停留、觀察，慢慢理解。',true,'[{"type": "paragraph", "text": "這裡是台灣四山之路的四個主要到訪點之一。第一次的旅行，希望留下一段從容的停留，看看人們如何在日常中實踐信念。"}, {"type": "heading", "text": "參訪前"}, {"type": "paragraph", "text": "詳細交通、開放時段與參訪規定尚待查核整理，請以道場官方公告為準。若希望參與服務，須事先聯繫確認。"}, {"type": "heading", "text": "留給旅程的空白"}, {"type": "paragraph", "text": "參訪後，這裡會逐步加入實際觀察、照片與相關手記。"}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127PostTranslation"("PostID","Language","Title","Summary","IsPublished","Blocks") VALUES('12700000-0000-4000-8000-000000000110','en','Dharma Drum Mountain','One of four places to pause, observe and understand.',true,'[{"type": "paragraph", "text": "This is one of the four main stops on the Taiwan Four Mountains Route. On my first visit, I hope to take time to observe how people live out their beliefs in everyday life."}, {"type": "heading", "text": "Before visiting"}, {"type": "paragraph", "text": "Transport details, opening times and visiting arrangements are still being checked. Consult official announcements before departure. Any volunteering must be arranged in advance."}, {"type": "heading", "text": "Room for the journey"}, {"type": "paragraph", "text": "Observations, photographs and journal entries will be added after the visit."}]'::jsonb) ON CONFLICT DO NOTHING;
