INSERT INTO public."TblP127PostTranslation"("PostID","Language","Title","Summary","IsPublished","Blocks") VALUES('12700000-0000-4000-8000-000000000120','en','Jing Si Abode — Dharma Drum Mountain','In planning · By public transport and on foot.',true,'[{"type": "paragraph", "text": "This connection describes the sequence between two stops, not a continuous walking trail. Transfers, accommodation and schedules will be added once confirmed."}, {"type": "paragraph", "text": "For the first year, the plan is to stay in city centres and reach the temples by public transport and on foot. The journey will help test how practical this approach is."}, {"type": "paragraph", "text": "No verified transport itinerary is provided here yet. Please do not use this page as a boarding guide."}]'::jsonb) ON CONFLICT DO NOTHING;
