INSERT INTO public."TblP127PostTranslation"("PostID","Language","Title","Summary","IsPublished","Blocks") VALUES('12700000-0000-4000-8000-000000000123','zh','佛光山—靜思精舍','規劃中・搭車、步行，也為途中留一點時間。',true,'[{"type": "paragraph", "text": "這段連線表示兩個停留點之間的旅行方向，並非連續步道。實際轉乘、住宿與班次，將在確認後補上。"}, {"type": "paragraph", "text": "第一年暫以大都市市區為住宿基地，利用大眾運輸與步行前往道場。市區住宿是否更省時省力，將由實際旅程驗證。"}, {"type": "paragraph", "text": "此頁尚未提供已查核的交通方案，請勿直接作為乘車指引。"}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127PostTranslation"("PostID","Language","Title","Summary","IsPublished","Blocks") VALUES('12700000-0000-4000-8000-000000000123','en','Fo Guang Shan — Jing Si Abode','In planning · By public transport and on foot.',true,'[{"type": "paragraph", "text": "This connection describes the sequence between two stops, not a continuous walking trail. Transfers, accommodation and schedules will be added once confirmed."}, {"type": "paragraph", "text": "For the first year, the plan is to stay in city centres and reach the temples by public transport and on foot. The journey will help test how practical this approach is."}, {"type": "paragraph", "text": "No verified transport itinerary is provided here yet. Please do not use this page as a boarding guide."}]'::jsonb) ON CONFLICT DO NOTHING;
