INSERT INTO public."TblP127Post"("PostID","Slug","Category","Status","JourneyID","RecordDate","CheckedAt","SortOrder","Revision","CreatedAt","UpdatedAt") VALUES('12700000-0000-4000-8000-000000000130','first-journey-2026','journal','published','12700000-0000-4000-8000-000000000020',NULL,NULL,130,1,'2026-09-21T00:00:00Z','2026-09-21T00:00:00Z') ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127PostTranslation"("PostID","Language","Title","Summary","IsPublished","Blocks") VALUES('12700000-0000-4000-8000-000000000130','zh','2026・第一次走四山','預計十月或十一月，留五天四夜給台灣。',true,'[{"type": "paragraph", "text": "這趟旅程暫定於2026年10月或11月出發，安排五天四夜。確切日期、住宿與交通尚未決定。"}, {"type": "paragraph", "text": "第一年的想法，是以台北、台中、高雄、花蓮市區作為住宿基地的候選，清晨再搭大眾運輸前往四山。這些城市尚非已訂定的四晚住宿安排。"}, {"type": "paragraph", "text": "我想記下的不只是景點，還有候車、轉乘、步行與停留的感受。走完之後，再想下一年是否住得離四山更近一些。"}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127PostTranslation"("PostID","Language","Title","Summary","IsPublished","Blocks") VALUES('12700000-0000-4000-8000-000000000130','en','2026 · A first journey','Five days and four nights, planned for October or November.',true,'[{"type": "paragraph", "text": "The first journey is provisionally planned for October or November 2026, over five days and four nights. Dates, accommodation and transport have not yet been decided."}, {"type": "paragraph", "text": "Taipei, Taichung, Kaohsiung and Hualien city centres are being considered as overnight bases, with early public transport to the four stops. This is not yet a confirmed four-night accommodation plan."}, {"type": "paragraph", "text": "I want to record more than destinations: the waiting, transfers, walks and unhurried pauses. Afterwards, I can consider staying closer to the temples in a future year."}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127Post"("PostID","Slug","Category","Status","JourneyID","RecordDate","CheckedAt","SortOrder","Revision","CreatedAt","UpdatedAt") VALUES('12700000-0000-4000-8000-000000000140','before-departure','prepare','published',NULL,NULL,NULL,140,1,'2026-09-21T00:00:00Z','2026-09-21T00:00:00Z') ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127PostTranslation"("PostID","Language","Title","Summary","IsPublished","Blocks") VALUES('12700000-0000-4000-8000-000000000140','zh','出發之前','準備一些，也為變化留一些空間。',true,'[{"type": "list", "text": "選擇起點、方向與預計天數\n確認各道場當日參訪規定\n查核班次、末班車與轉乘時間\n訂妥住宿，確認行李寄放方式\n準備步行用品、雨具與飲水\n若想參與服務，事先聯繫\n尊重他人，拍攝人物前先徵求同意"}, {"type": "paragraph", "text": "網站中的交通與住宿紀錄會標註查核日期或體驗日期；價格、班次與開放安排仍須在出發前再次確認。"}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127PostTranslation"("PostID","Language","Title","Summary","IsPublished","Blocks") VALUES('12700000-0000-4000-8000-000000000140','en','Before you leave','Make room for both preparation and change.',true,'[{"type": "list", "text": "Choose your starting point, direction and number of days\nCheck visiting arrangements for each stop\nVerify schedules, last departures and transfers\nBook accommodation and check luggage storage\nBring walking essentials, rain protection and water\nArrange any volunteering in advance\nAsk permission before photographing people"}, {"type": "paragraph", "text": "Transport and accommodation records will show when they were checked or experienced. Reconfirm prices, schedules and visiting arrangements before departure."}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127Post"("PostID","Slug","Category","Status","JourneyID","RecordDate","CheckedAt","SortOrder","Revision","CreatedAt","UpdatedAt") VALUES('12700000-0000-4000-8000-000000000150','annual-book','books','published',NULL,NULL,NULL,150,1,'2026-09-21T00:00:00Z','2026-09-21T00:00:00Z') ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127PostTranslation"("PostID","Language","Title","Summary","IsPublished","Blocks") VALUES('12700000-0000-4000-8000-000000000150','zh','一本可以帶上路的小書','A6・資訊與留白，留給每年的自己。',true,'[{"type": "paragraph", "text": "《台灣四山之路》規劃為A6小書，約64頁。從出發之前、四座名山、四段旅程，到回來之後，安排十章，留出書寫與回望的空間。"}, {"type": "paragraph", "text": "目前仍在編寫與設計中。先前封面以2027為示例年份，並非已出版版本。完成可分享的版本後，將於此提供資訊與檔案。"}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."TblP127PostTranslation"("PostID","Language","Title","Summary","IsPublished","Blocks") VALUES('12700000-0000-4000-8000-000000000150','en','A small book for the road','A6 · Practical notes and room for your own words.',true,'[{"type": "paragraph", "text": "Taiwan Four Mountains Route is planned as an A6 book of about 64 pages, with ten chapters covering preparation, the four stops, four connecting journeys and reflections after returning. Space will be left for readers to write."}, {"type": "paragraph", "text": "Writing and design are in progress. The cover concept used 2027 as an example year; it is not a published edition. Information and files will be added when a shareable version is ready."}]'::jsonb) ON CONFLICT DO NOTHING;
